#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int android = 0, ios = 0;
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        if (x == 1) android++;
        else ios++;
    }
    printf("%d %d\n", android, ios);
    return 0;
}
